export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * tTop));

  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let state = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) state = "Rising";
  else if (Math.abs(t - tTop) <= 0.05) state = "At the top";
  else if (t > tTop + 0.05 && y > 0) state = "Falling";
  else if (y <= 0 && t > 0) state = "Back at launch height";

  const laneW = 280;
  const laneH = 340;
  const leftX = 30;
  const topY = 50;

  const objects = [];
  objects.push(...sdk.panel({ x: leftX, y: topY, w: laneW, h: laneH, title: "The Motion", state }));

  const scaleY = 100;
  const baseY = topY + 280;
  const ballY = baseY - y * scaleY;
  const ballX = leftX + 140;

  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "observed" }));

  objects.push(...sdk.axis("axis.height", {
    x: leftX + 50,
    y: baseY,
    length: 220,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(...sdk.vector("vec.v", { x: ballX - 20, y: ballY }, { value: v, direction: "up" }, { scale: 15, label: "v", role: "input" }));
  objects.push(...sdk.vector("vec.a", { x: ballX + 20, y: ballY }, { value: a, direction: "up" }, { scale: 5, label: "a", role: "prediction" }));

  objects.push(...sdk.callout(ballX + 45, ballY - 20, [
    `velocity: ${v.toFixed(2)} m/s`,
    `acceleration: ${a.toFixed(2)} m/s^2`,
    `force: ${Fg.toFixed(1)} N`
  ], { id: "callout.toss" }));

  const plotX = 330;
  const plotY = 50;
  const plotW = 280;
  const plotH = 340;

  objects.push(...sdk.panel({ x: plotX, y: plotY, w: plotW, h: plotH, title: "Velocity over Time", state: `t = ${t.toFixed(2)} s` }));

  const points = [];
  const totalT = 2 * tTop;
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const st = (i / steps) * totalT;
    const sv = u - g * st;
    points.push([st, sv]);
  }

  const currentPoints = [];
  const currSteps = Math.max(2, Math.floor((t / totalT) * steps));
  for (let i = 0; i <= currSteps; i++) {
    const st = (i / steps) * totalT;
    const sv = u - g * st;
    currentPoints.push([st, sv]);
  }

  objects.push(sdk.plot("plot.vt", {
    x: plotX + 20,
    y: plotY + 40,
    w: plotW - 40,
    h: plotH - 80,
    axes: {
      x: { label: "Time", min: 0, max: Math.max(1.8, totalT), unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points }
    ],
    marker: { x: t, y: v, label: "now" }
  }));

  objects.push(sdk.text("plot.vt.note", plotX + 30, plotY + 310, `Slope a = -g = ${a.toFixed(1)} m/s^2`, { role: "observed" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(Fg.toFixed(2)) },
        { id: "motionState", value: state }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
